def processar(comando, estado):
    partes = comando.split()
    if len(partes) == 2 and partes[0] == "ir":
        nova = mover(estado["sala"], partes[1])
        if nova == estado["sala"]:
            return "Não dá para ir por aí."
        estado["sala"] = nova
        return descrever(nova)
    if len(partes) == 2 and partes[0] == "pegar":
        if pegar(partes[1], estado["sala"], estado["inventario"]):
            return f"Você pegou: {partes[1]}."
        return "Não tem isso aqui."
    if comando == "inventario":
        if not estado["inventario"]:
            return "Você não leva nada."
        return "Você leva: " + ", ".join(estado["inventario"]) + "."
    return "Não entendi."

